import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Calculate effect sizes (mean difference in outcome groups)
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test
            group0 = feats.x[feats.y == 0, i]
            group1 = feats.x[feats.y == 1, i]
            if len(group0) > 0 and len(group1) > 0:
                t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
                effect_sizes.append(abs(t_stat))
            else:
                effect_sizes.append(0)
        else:
            # For other features, use correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            effect_sizes.append(abs(corr))

    # Sort by effect size
    sorted_indices = np.argsort(effect_sizes)[::-1]

    # Select top candidates
    candidates = []
    seen_ids = set()

    for idx in sorted_indices:
        fid = feats.ids[idx]
        # Skip near-duplicates (correlated features)
        is_duplicate = False
        for existing_fid in seen_ids:
            if abs(np.corrcoef(feats.x[:, feats.column(existing_fid)], 
                               feats.x[:, feats.column(fid)])[0, 1]) >= 0.6:
                is_duplicate = True
                break

        if not is_duplicate:
            candidates.append(fid)
            seen_ids.add(fid)
            if len(candidates) >= MAX_DRIVERS:
                break

    # If no strong candidate found, return empty design
    if not candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build the design with minimal terms
    drivers = tuple(candidates)
    columns = tuple(candidates)  # Only include drivers in regression
    products = ()
    loadings = {fid: 1.0 for fid in candidates}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

